  c.shadowBlur = 28 * S;
  c.shadowOffsetY = 10 * S;
  c.fillStyle = "#0E141F";
  c.beginPath(); c.arc(cx, cy, r, 0, Math.PI * 2); c.fill();
  c.shadowColor = "transparent";

  // Magnified circular crop
  c.save();
  c.beginPath(); c.arc(cx, cy, r - 4 * S, 0, Math.PI * 2); c.clip();
  c.drawImage(snap, cx - r, cy - r, r * 2, r * 2);
