  const gl = c.createLinearGradient(cx - r, cy - r, cx + r * 0.4, cy + r * 0.4);
  gl.addColorStop(0, "rgba(255,255,255,0.34)");
  gl.addColorStop(0.35, "rgba(255,255,255,0.05)");
